/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);const data=p.data??[],max=Math.max(1,...data.map(x=>x.value));return <figure className={`anu-rich-chart bars ${p.orientation}`}><figcaption><strong>{p.title}</strong>{p.subtitle&&<span>{p.subtitle}</span>}</figcaption><div className="bar-plot">{data.map((x)=><div className="bar-item" key={x.label} title={`${x.label}: ${x.value}${p.unit??""}`}><span className="bar" style={{"--value":`${(x.value/max)*100}%`}}/><small>{x.label}</small><b>{x.value}{p.unit}</b></div>)}</div></figure>}
